<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue';import {operationMessage,type LocalLauncherClient} from './local-api';
import type {GameInstance,InstanceModListing,TaskSnapshot} from './local-types';import InstanceModDialog from './InstanceModDialog.vue';
const props=defineProps<{client:LocalLauncherClient;instance:GameInstance;revision?:number}>();const emit=defineEmits<{submitted:[task:TaskSnapshot]}>();
const listing=ref<InstanceModListing|null>(null),error=ref(''),loading=ref(false),operation=ref<'REMOVE'|'FABRIC_API'|null>(null);let controller=new AbortController(),sequence=0,queued=false,alive=true;
async function load(){if(!alive)return;if(loading.value){queued=true;return;}listing.value=null;controller.abort();controller=new AbortController();const current=++sequence;loading.value=true;error.value='';try{const value=await props.client.instanceMods(props.instance.id,controller.signal);if(current===sequence)listing.value=value;}catch(e){if(current===sequence)error.value=operationMessage(e);}finally{if(alive&&current===sequence){loading.value=false;if(queued){queued=false;void load();}}}}
function submitted(task:TaskSnapshot){operation.value=null;emit('submitted',task);}
watch([()=>props.instance.id,()=>props.revision],()=>{void load();},{immediate:true});onBeforeUnmount(()=>{alive=false;queued=false;++sequence;controller.abort();});
</script>
<template><section class="launcher-glass instance-mods" data-instance-mods><div class="launcher-modal-title"><div><span class="launcher-overline">INSTANCE MODS</span><h2>{{instance.name}} · 模组</h2></div><button class="launcher-secondary" data-refresh-instance-mods :disabled="loading" @click="load">刷新 ↻</button></div><p v-if="error" class="launcher-inline-notice" role="alert">{{error}}</p><p v-if="loading" role="status">正在读取和校验实例模组…</p><template v-if="listing"><p class="launcher-caption">{{listing.entries.length}} 个受管模组 · {{listing.manualFiles}} 个手动文件。安装新模组请前往发现模组；手动文件不会自动删除或覆盖。</p><p v-if="!listing.compatible" class="launcher-inline-notice">当前核心已改变，请先移除旧核心的受管模组，再选择新核心的兼容文件。</p><div class="instance-mod-actions"><button v-if="listing.loader==='fabric'&&listing.compatible" class="launcher-secondary" data-install-fabric-api @click="operation='FABRIC_API'">安装 Fabric API</button><button v-if="listing.entries.length" class="launcher-secondary" data-remove-instance-mods @click="operation='REMOVE'">移除全部受管模组…</button></div><p v-if="!listing.entries.length" class="launcher-caption">尚无受管模组。已安装加载器后，可以从发现页选择兼容文件装入。</p><article v-for="entry in listing.entries" :key="entry.source+entry.projectId" class="instance-mod-row" :data-managed-mod="entry.projectId"><strong>{{entry.displayName||entry.fileName}}</strong><span>{{entry.fileName}} · {{(entry.size/1048576).toFixed(2)}} MiB</span><small>{{entry.source}} · {{entry.versionId}}</small></article><code class="instance-mod-path">{{listing.directory}}</code></template></section><InstanceModDialog v-if="operation" :client="client" :instance="instance" :operation="operation" @close="operation=null" @submitted="submitted"/></template>
<style scoped>.instance-mods{padding:24px;margin:24px 0}.instance-mod-actions{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0}.instance-mod-row{display:grid;gap:4px;padding:16px 0}.instance-mod-row span,.instance-mod-row small{color:var(--launcher-muted)}.instance-mod-path{display:block;overflow-wrap:anywhere;font-size:12px;opacity:.7;margin-top:20px}</style>
